"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0538-01-01:0":{"b": ["عيلام (عيلام القديمة - عيلام الجديدة): تنتهي فترة عيلام الجديدة", "64fe1dfe"], "d": ["أسرة أوان (نحو 2400-2100 ق.م)، شيماشكي، الإبارتيون/السوكّلماه (معاصرو بابل القديمة)؛ عيلام الوسطى (أونتاش-ناپيريشا نحو 1340-1300، تشوغا زنبيل)؛ عيلام الجديدة (1100-539). يرد اسم عيلام في المصدر أول مرة في نص ملك كيش إنمباراغيسي (نحو 2650 ق.م)؛ عيلام الجديدة II نحو 770-646 (الصراع مع آشور).", "e35bcb7b"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0558-01-01:0":{"b": ["الإمبراطورية الأخمينية / مملكة قورش الثاني في برسيس: قورش الثاني يعتلي العرش الفارسي (559)", "c0d9c31b"], "d": ["559: بداية حكم قورش الثاني (حدّ العهد الذي تعطيه مادة باسارغاد)؛ 550: خلع الملك الميدي أستياغ وتوحيد إيران (شميت)؛ 330: نهاية دارا الثالث.", "5a8e254a"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0699-01-01:0":{"b": ["الدولة الميدية (مركزها هگمتانه): الدولة الميدية: تبدأ فترة ديوكيس (تقليد هيرودوت)", "26e483d1"], "d": ["الوحدة السياسية/الدولة للميديين: يبدأها تقليد هيرودوت بديوكيس (نحو 700-647)؛ أما تسلسل غرانتوفسكي البديل القائم على المصادر الآشورية فيضع التمرد الميدي نحو 672 وديوكيس نحو 672/671. وأستياغ آخر ملوك الميديين أطاح به قورش سنة 550 ق.م (الحرب الميدية-الفارسية 553-550).", "ce4a8a35"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-2169-01-01:0":{"b": ["تيبي حصار: تنتهي المرحلة IIIC", "be19ff7c"], "d": ["تلّ من العصر النحاسي-البرونزي المبكر قرب دامغان (حصار I-III)؛ بحسب الكربون 14 المعايَر IC/IIA نحو 3980-3865 ق.م، IIB 3365-3030، IIIB 2400-2170، IIIC 2170-1900.", "505d235c"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-2399-01-01:0":{"b": ["عيلام (عيلام القديمة - عيلام الجديدة): تبدأ أسرة أوان (أول أسرة عيلامية)", "b8a35586"], "d": ["أسرة أوان (نحو 2400-2100 ق.م)، شيماشكي، الإبارتيون/السوكّلماه (معاصرو بابل القديمة)؛ عيلام الوسطى (أونتاش-ناپيريشا نحو 1340-1300، تشوغا زنبيل)؛ عيلام الجديدة (1100-539). يرد اسم عيلام في المصدر أول مرة في نص ملك كيش إنمباراغيسي (نحو 2650 ق.م)؛ عيلام الجديدة II نحو 770-646 (الصراع مع آشور).", "e35bcb7b"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-3199-01-01:0":{"b": ["نظام الكتابة العيلامي الأولي (سوسة): تظهر الكتابة العيلامية الأولية", "a88d66b7"], "d": ["نظام كتابة عيلامي أولي لم يُفكّ، معاصر لأوروك III في سوسة؛ ينتشر في ثمانية مواقع على الهضبة الإيرانية. أما «نحو 3100 ق.م» الوارد في الموجز فلم يوجد في مصدر واحد؛ والمصادر تعطي بداية 3200.", "e4504100"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-3921-01-01:0":{"b": ["تيبي حصار: تبدأ المرحلة IC/IIA (أقدم مرحلة مؤرَّخة بالكربون 14)", "8d917577"], "d": ["تلّ من العصر النحاسي-البرونزي المبكر قرب دامغان (حصار I-III)؛ بحسب الكربون 14 المعايَر IC/IIA نحو 3980-3865 ق.م، IIB 3365-3030، IIIB 2400-2170، IIIC 2170-1900.", "505d235c"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-3999-01-01:0":{"b": ["سوسة: تأسيس المدينة (تقريبًا، Iranica)", "63ff02c7"], "d": ["مركز سوزيانا؛ يعطي Iranica تأسيسها نحو 4000 ق.م. وتشترك سوسة II المتأخرة (نحو 3500-3100 ق.م) مع أوروك في الثقافة المادية نفسها؛ ثم يأتي العصر العيلامي الأولي، والفتح الأكدي (نحو 2300 ق.م)، وإدخالها في أور III (سوسة VB)، والممالك العيلامية.", "39f0c741"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-4299-01-01:0":{"b": ["أناو IA وأفق ميانا (كوبت داغ، العصر النحاسي المبكر): مرحلة أناو Ia (أدنى الطبقات)", "14def83f"], "d": ["العصر النحاسي بعد جيتون عند سفوح كوبت داغ؛ عُرِّف في مونجوكلي تپه «أفق ميانا» مستقل قبل أناو IA (نحو 4650-4340 ق.م معايَر).", "5d2520ea"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-5499-01-01:0":{"b": ["تيبي يحيى: تبدأ الفترة VII (Iranica؛ جدول مؤقت)", "9396a756"], "d": ["تلّ في جنوب شرق إيران ذو تتابع طبقي طويل؛ الفترة VII (العصر الحجري الحديث الفخاري، 5500-4500)، الفترة IVC2 (3100-2800) مجمع مبانٍ كبير ذو ألواح عيلامية أولية ولقى من طراز سوسة III؛ IVB 2400-2000؛ IVA 1800-1400؛ III 800-500؛ II 500-275؛ I 200 ق.م-300 م.", "a059993d"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-5919-01-01:0":{"b": ["غادخريلي غورا: شولافيري-شوموتيبه: الطبقات الأولى للتل", "3c414a94"], "d": ["تلّ شولافيري-شوموتيبه في كفيمو كارتلي (مارنيولي)؛ مرحلتا استيطان، ووحدات دائرية وبنى للتخزين.", "115962d7"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-5926-01-01:0":{"b": ["جيتون: ينتهي استيطان جيتون (بايز)", "3d5b7e57"], "d": ["قرية مبكرة عند سفوح كوبت داغ في جنوب تركمانستان يزرع أهلها الشعير والقمح ويربّون الأغنام والماعز؛ بحسب نموذج الكربون 14 البايزي نحو 6200-5850 ق.م.", "91c177c4"]},
